mapper.sql:
FROM BTCH_BAS A WHERE 1=1
AND (BTCH_JOB_NM LIKE CONCAT('%', #{btchJobNm}, '%') OR BTCH_JOB_ID LIKE CONCAT('%', #{btchJobNm}, '%'))
AND BTCH_CYCL_CD = #{btchCyclCd}

mapper.select:
/*BtchBasDAO.selectListBtchBas 배치기본 목록 조회 */
SELECT A.BTCH_JOB_ID /* 배치작업코드 */ , A.BTCH_JOB_NM /* 배치작업명 */ , A.BTCH_CYCL_CD /* 배치주기코드 */ , A.BTCH_EXE_PGM_NM /* 배치실행프로그램명 */ , A.RE_EXE_POSBL_YN /* 재실행가능여부 */ , A.BTCH_EXE_DESIG_DD /* 배치실행지정일 */ , A.BTCH_JOB_TTM /* 배치작업시간 */ , A.CRON_EXRS /* CRON표현 */ , A.AUTO_EXE_YN /* 자동실행여부 */ , A.APLY_START_DT /* 적용시작일자 */ , A.APLY_END_DT /* 적용종료일자 */ , A.DESC_CTNT /* 설명내용 */ , A.USE_YN /* 사용여부 */ , A.FRST_REGI_USER_ID /* 최초등록사용자아이디 */ , A.FRST_REGI_TMSP /* 최초등록타임스탬프 */ , A.LAST_CHNG_USER_ID /* 최종변경사용자아이디 */ , A.LAST_CHNG_TMSP /* 최종변경타임스탬프 */ , (SELECT CD_NM FROM CMN_CD WHERE CD_GROUP_VAL = 'BTCH_CYCL_CD' AND CD_VAL = A.BTCH_CYCL_CD AND USE_YN = 'Y') BTCH_CYCL_NM
ORDER BY A.BTCH_JOB_ID
